operation.add:
require_once(DIR_TEMPLATE . 'evrika/php/icons.php');
$_evrika_icons = evrika_get_icons();
$_icon1 = $this->config->get('evrika_promo_banner1_icon') ?: 'briefcase';
$_icon2 = $this->config->get('evrika_promo_banner2_icon') ?: 'tag';
$data['promo1_title']    = $this->config->get('evrika_promo_banner1_title') ?: 'Открой своё дело';
$data['promo1_desc']     = $this->config->get('evrika_promo_banner1_desc')  ?: 'Франшиза КанцПарк — от 1 млн ₽';
$data['promo1_icon_svg'] = isset($_evrika_icons[$_icon1]) ? $_evrika_icons[$_icon1]['svg'] : '';
$data['promo1_link']     = $this->config->get('evrika_promo_banner1_link')  ?: '';
$data['promo2_title']    = $this->config->get('evrika_promo_banner2_title') ?: 'Коллекция 2026';
$data['promo2_desc']     = $this->config->get('evrika_promo_banner2_desc')  ?: 'Школьный текстиль — уже в продаже';
$data['promo2_icon_svg'] = isset($_evrika_icons[$_icon2]) ? $_evrika_icons[$_icon2]['svg'] : '';
$data['promo2_link']     = $this->config->get('evrika_promo_banner2_link')  ?: '';
